import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        StringBuilder processed = new StringBuilder();
        processed.append(s.charAt(0));
        int total_length = s.length();
        int index = 1;
        while (index < total_length) {
            if (index + 2 < total_length && s.charAt(index) == 'd' && s.charAt(index + 1) == 'o' && s.charAt(index + 2) == 't') {
                processed.append('.');
                index += 3;
            } else {
                processed.append(s.charAt(index));
                index++;
            }
        }
        StringBuilder output_str = new StringBuilder();
        output_str.append(processed.charAt(0));
        boolean at_replaced_flag = false;
        int k = 1;
        while (k < processed.length()) {
            if (!at_replaced_flag && k + 1 < processed.length() && processed.charAt(k) == 'a' && processed.charAt(k + 1) == 't') {
                output_str.append('@');
                k += 2;
                at_replaced_flag = true;
            } else {
                output_str.append(processed.charAt(k));
                k++;
            }
        }
        System.out.print(output_str.toString());
        sc.close();
    }
}
